type PipelineStep = {
  /** Legacy prop, no longer rendered — steps carry mono markers instead. */
  emoji?: string;
  title: string;
  detail?: string;
};

type PipelineDiagramProps = {
  title?: string;
  steps: PipelineStep[];
};

const TICKS = [
  "left-0 top-0 -translate-x-1/2 -translate-y-1/2",
  "right-0 top-0 translate-x-1/2 -translate-y-1/2",
  "left-0 bottom-0 -translate-x-1/2 translate-y-1/2",
  "right-0 bottom-0 translate-x-1/2 translate-y-1/2",
];

function CornerTicks() {
  return (
    <>
      {TICKS.map((pos) => (
        <span
          key={pos}
          aria-hidden="true"
          class={`absolute ${pos} font-mono text-[9px] leading-none text-[var(--color-page-text-muted)]`}
        >
          +
        </span>
      ))}
    </>
  );
}

export function PipelineDiagram({ title, steps }: PipelineDiagramProps) {
  return (
    <div class="relative my-8 border border-[var(--color-page-border)] bg-[var(--color-page-surface-dim)] p-4 sm:p-5">
      <CornerTicks />
      {title && (
        <div class="mb-4 font-mono text-[10px] uppercase tracking-[0.22em] text-[var(--color-page-text-muted)]">
          {title}
        </div>
      )}
      <div class="flex flex-col gap-1.5">
        {steps.map((step, index) => (
          <div key={step.title} class="contents">
            <div class="border border-[var(--color-page-border)] bg-[var(--color-page-bg)] px-3 py-2.5 sm:px-4 sm:py-3">
              <div class="grid gap-1.5 sm:grid-cols-[minmax(0,12rem)_1fr] sm:gap-3">
                <div>
                  <div class="font-mono text-[10px] uppercase tracking-[0.18em] text-[var(--color-page-text-muted)]">
                    Step{" "}
                    <span class="text-[var(--color-tg-accent)]">
                      {String(index + 1).padStart(2, "0")}
                    </span>
                  </div>
                  <div class="mt-0.5 flex items-baseline gap-2 text-[0.98rem] font-semibold leading-tight text-[var(--color-page-text)] sm:text-[1rem]">
                    <span
                      aria-hidden="true"
                      class="font-mono text-[10px] text-[var(--color-tg-accent)]"
                    >
                      ▪
                    </span>
                    <span>{step.title}</span>
                  </div>
                </div>
                {step.detail && (
                  <div class="text-[0.92rem] leading-6 text-[var(--color-page-text-muted)] sm:self-center">
                    {step.detail}
                  </div>
                )}
              </div>
            </div>
            {index < steps.length - 1 && (
              <div
                aria-hidden="true"
                class="flex items-center justify-center py-1 font-mono text-sm leading-none text-[var(--color-tg-accent)]"
              >
                ↓
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

