/**
 * Animated "operating loop" for the blog post, shown as a full closed loop:
 *
 *   batch of events stream in  →  written to the append-only log (entities
 *   derived)  →  a behavior fires and the agent acts, and every action emits a
 *   NEW event  →  which flows back into the stream. The loop.
 *
 * The incoming events are a live marquee (a stack streaming past), including a
 * couple the agent generated itself, so the loop visibly closes. Pure CSS
 * keyframes, no hydration.
 */

const ACCENT = "var(--color-tg-accent)";

type Ev = { src: string; name: string; ent?: string; gen?: boolean };

// The batch flowing in: real-looking source events, plus two the agent emitted
// last pass (gen: true), so you can see the loop feeding itself.
const EVENTS: Ev[] = [
  { src: "stripe", name: "payment_failed", ent: "Acme" },
  { src: "typeform", name: "lead.created" },
  { src: "agent", name: "note.created", ent: "Acme", gen: true },
  { src: "sentry", name: "error.spike" },
  { src: "gmail", name: "reply", ent: "Globex" },
  { src: "agent", name: "ticket.opened", gen: true },
  { src: "hubspot", name: "deal.won" },
  { src: "slack", name: "mention" },
];

const TICKS = [
  "left-0 top-0 -translate-x-1/2 -translate-y-1/2",
  "right-0 top-0 translate-x-1/2 -translate-y-1/2",
  "left-0 bottom-0 -translate-x-1/2 translate-y-1/2",
  "right-0 bottom-0 translate-x-1/2 translate-y-1/2",
];

function CornerTicks() {
  return (
    <>
      {TICKS.map((pos) => (
        <span
          key={pos}
          aria-hidden="true"
          class={`absolute ${pos} font-mono text-[9px] leading-none`}
          style={{ color: "var(--color-page-text-muted)" }}
        >
          +
        </span>
      ))}
    </>
  );
}

function EventRow({ ev }: { ev: Ev }) {
  return (
    <div class="mb-1.5 flex items-center gap-1.5 whitespace-nowrap">
      <span
        class="border px-1 py-px font-mono text-[8.5px]"
        style={{
          color: ev.gen ? ACCENT : "var(--color-page-text-muted)",
          borderColor: ev.gen
            ? "var(--color-page-border-active)"
            : "var(--color-page-border)",
          backgroundColor: "var(--color-page-surface)",
        }}
      >
        {ev.src}
      </span>
      <span
        class="font-mono text-[10px]"
        style={{ color: "var(--color-page-text)" }}
      >
        {ev.name}
      </span>
      {ev.ent ? (
        <span
          class="font-mono text-[9px]"
          style={{ color: "var(--color-page-text-muted)" }}
        >
          · {ev.ent}
        </span>
      ) : null}
    </div>
  );
}

function Card({
  step,
  title,
  sub,
  grow = 1,
  children,
}: {
  step: string;
  title: string;
  sub: string;
  grow?: number;
  children: preact.ComponentChildren;
}) {
  return (
    <div
      class="relative flex min-w-0 flex-col gap-1.5 border p-3.5"
      style={{
        flex: `${grow} 1 0%`,
        borderColor: "var(--color-page-border)",
        backgroundColor: "var(--color-page-bg)",
      }}
    >
      <div class="flex items-baseline gap-1.5">
        <span
          aria-hidden="true"
          class="shrink-0 font-mono text-[9.5px]"
          style={{ color: ACCENT }}
        >
          {step}
        </span>
        <span
          class="text-[12.5px] font-semibold leading-tight"
          style={{ color: "var(--color-page-text)" }}
        >
          {title}
        </span>
      </div>
      <span
        class="text-[10px] leading-snug"
        style={{ color: "var(--color-page-text-muted)" }}
      >
        {sub}
      </span>
      {children}
    </div>
  );
}

function Chip({ label }: { label: string }) {
  return (
    <span
      class="border px-1.5 py-0.5 font-mono text-[9.5px]"
      style={{
        color: ACCENT,
        borderColor: "var(--color-page-border-active)",
        backgroundColor: "var(--color-page-surface)",
      }}
    >
      {label}
    </span>
  );
}

function Connector() {
  return (
    <div
      class="relative hidden h-px flex-[0_0_26px] self-center sm:block"
      style={{ backgroundColor: "var(--color-page-border)" }}
    >
      <span
        class="flow-pip absolute top-1/2 h-1.5 w-1.5 -translate-y-1/2"
        style={{ backgroundColor: ACCENT }}
      />
    </div>
  );
}

export function EventLoopAnimation() {
  const stream = [...EVENTS, ...EVENTS];
  return (
    <div
      class="not-prose relative my-7 border p-4"
      style={{
        borderColor: "var(--color-page-border)",
        backgroundColor: "var(--color-page-surface-dim)",
      }}
    >
      <CornerTicks />
      <div
        class="mb-3 font-mono text-[10px] uppercase tracking-[0.22em]"
        style={{ color: "var(--color-page-text-muted)" }}
      >
        The operating loop
      </div>
      <div class="flex flex-col gap-2.5 sm:flex-row sm:items-stretch sm:gap-0">
        {/* 1. batch of events streaming in */}
        <Card
          step="01"
          title="Events stream in"
          sub="webhooks + connectors, batched"
          grow={1.25}
        >
          <div
            class="ev-stream relative mt-1 overflow-hidden"
            style={{
              height: "104px",
              maskImage:
                "linear-gradient(to bottom, transparent, #000 16%, #000 84%, transparent)",
              WebkitMaskImage:
                "linear-gradient(to bottom, transparent, #000 16%, #000 84%, transparent)",
            }}
          >
            <div class="ev-track">
              {stream.map((ev, i) => (
                <EventRow key={`${ev.src}-${ev.name}-${i}`} ev={ev} />
              ))}
            </div>
          </div>
        </Card>

        <Connector />

        {/* 2. written to the append-only log, entities derived */}
        <Card
          step="02"
          title="Written to the log"
          sub="append-only · every event a row"
        >
          <div
            class="mt-0.5 border px-2 py-1.5 font-mono text-[9.5px]"
            style={{
              borderColor: "var(--color-page-border)",
              backgroundColor: "var(--color-page-surface)",
              color: "var(--color-page-text-muted)",
            }}
          >
            <div class="flex justify-between">
              <span>event_id</span>
              <span>source</span>
            </div>
            {[
              ["a1f9…", "stripe"],
              ["b2c4…", "sentry"],
              ["c3d7…", "agent"],
            ].map(([id, src]) => (
              <div
                key={id}
                class="flex justify-between"
                style={{ color: "var(--color-page-text)" }}
              >
                <span>{id}</span>
                <span>{src}</span>
              </div>
            ))}
          </div>
          <div class="mt-1 flex items-center gap-1.5">
            <span
              class="text-[9.5px]"
              style={{ color: "var(--color-page-text-muted)" }}
            >
              entity
            </span>
            <Chip label="Acme → at risk" />
          </div>
        </Card>

        <Connector />

        {/* 3. behavior fires, agent acts, each action emits a new event */}
        <Card
          step="03"
          title="Behavior fires, agent acts"
          sub="sandbox · your model · MCP tools"
        >
          <span class="font-mono text-[11px]" style={{ color: ACCENT }}>
            enterprise-churn-watch
          </span>
          <div class="flex flex-wrap gap-1">
            {["Stripe", "HubSpot", "Slack"].map((t) => (
              <span
                key={t}
                class="border px-1.5 py-0.5 font-mono text-[9.5px]"
                style={{
                  borderColor: "var(--color-page-border)",
                  color: "var(--color-page-text-muted)",
                  backgroundColor: "var(--color-page-surface)",
                }}
              >
                {t}
              </span>
            ))}
          </div>
          <span
            class="mt-1 text-[9.5px]"
            style={{ color: "var(--color-page-text-muted)" }}
          >
            each action emits an event:
          </span>
          <div class="flex flex-wrap gap-1">
            <Chip label="note.created" />
            <Chip label="ticket.opened" />
            <Chip label="message.sent" />
          </div>
        </Card>
      </div>

      {/* loop-back rail: emitted events flow back into the stream */}
      <div class="mt-3 flex items-center gap-2 px-1">
        <span
          class="font-mono text-[12px]"
          style={{ color: ACCENT }}
          aria-hidden="true"
        >
          ←
        </span>
        <div
          class="relative h-px min-w-6 flex-1"
          style={{ backgroundColor: "var(--color-page-border)" }}
        >
          <span
            class="flow-pip-rev absolute top-1/2 h-1.5 w-1.5 -translate-y-1/2"
            style={{ backgroundColor: ACCENT }}
          />
        </div>
        <span
          class="font-mono text-[10.5px]"
          style={{ color: "var(--color-page-text-muted)" }}
        >
          every action is a new event, back into the stream
        </span>
      </div>

      <style>{`
        @keyframes lobu-ev-scroll {
          from { transform: translateY(0); }
          to { transform: translateY(-50%); }
        }
        .ev-track { animation: lobu-ev-scroll 11s linear infinite; }
        @keyframes lobu-flow-x {
          0% { left: -4px; opacity: 0; }
          12% { opacity: 1; }
          88% { opacity: 1; }
          100% { left: calc(100% + 4px); opacity: 0; }
        }
        @keyframes lobu-flow-x-rev {
          0% { left: calc(100% + 4px); opacity: 0; }
          12% { opacity: 1; }
          88% { opacity: 1; }
          100% { left: -4px; opacity: 0; }
        }
        .flow-pip { animation: lobu-flow-x 2.4s linear infinite; }
        .flow-pip-rev { animation: lobu-flow-x-rev 3s linear infinite; }
        @media (prefers-reduced-motion: reduce) {
          .ev-track { animation: none; }
          .flow-pip, .flow-pip-rev { animation: none; opacity: 0.6; left: 50%; }
        }
      `}</style>
    </div>
  );
}

