import { Frame, SectionHead, useReveal } from "./chrome";

type HardPart = {
	n: string;
	title: string;
	body: string;
	/** Lucide-style 24×24 stroked path, drawn like the hero's nav icons. */
	icon: string;
	/** Where the docs explain how Lobu closes this gap. */
	href: string;
};

function HardIcon({ d }: { d: string }) {
	return (
		<svg
			aria-hidden="true"
			class="lp-hard-ic"
			fill="none"
			stroke="currentColor"
			stroke-linecap="round"
			stroke-linejoin="round"
			stroke-width="1.75"
			viewBox="0 0 24 24"
		>
			<path d={d} />
		</svg>
	);
}

/**
 * The gap every agent interface has to close on its own. Ordered from the
 * concrete (systems, identity) to the durable (state, audit, churn), so the
 * grid reads as one argument rather than eight unrelated complaints.
 */
const HARD_PARTS: HardPart[] = [
	{
		n: "01",
		href: "/sdks/connectors/",
		title: "Fragmented systems",
		// scattered blocks — the same answer split across stores
		icon: "M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z",
		body: 'The answer lives across your CRM, warehouse, chat and docs — where "Acme", "acme-corp" and "Sarah from Acme" are all the same customer.',
	},
	{
		n: "02",
		href: "/guides/security/",
		title: "Identity and permissions",
		// key — acting as a specific person
		icon: "M15.5 7.5a4.5 4.5 0 1 1-4.32 5.8L4 20.5v-3h3v-3h3l1.18-1.2A4.5 4.5 0 0 1 15.5 7.5ZM16.5 11h.01",
		body: "An agent acting for Dana sees exactly what Dana sees, not what an admin token sees, and never another user's drafts.",
	},
	{
		n: "03",
		href: "/guides/tool-policy/",
		title: "Safe actions",
		// shield — a real action model, not raw keys
		icon: "M12 3l8 3v6c0 4.5-3.2 8.3-8 9.5-4.8-1.2-8-5-8-9.5V6zM9 12l2 2 4-4",
		body: "Handing an agent raw API keys and three hundred tools is not an action model.",
	},
	{
		n: "04",
		href: "/getting-started/memory/",
		title: "State that survives",
		// stacked layers — durable, not scrollback
		icon: "M12 3 3 7.5 12 12l9-4.5zM3 12l9 4.5L21 12M3 16.5 12 21l9-4.5",
		body: "Real work spans days and restarts; a chat scrollback is not durable state.",
	},
	{
		n: "05",
		href: "/guides/observability/",
		title: "Approvals and audit",
		// checked document — gate before, record after
		icon: "M14 3H6a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V8zM14 3v5h5M9 14l2 2 4-4",
		body: "Consequential actions need a human gate before, and a complete record after.",
	},
	{
		n: "06",
		href: "/getting-started/architecture/",
		title: "Tools keep changing",
		// cycle — interfaces churn, the layer under them shouldn't
		icon: "M21 12a9 9 0 0 1-9 9 9 9 0 0 1-7.9-4.7M3 12a9 9 0 0 1 9-9 9 9 0 0 1 7.9 4.7M3 21v-5h5M21 3v5h-5",
		body: "Models and interfaces will churn for years; the context layer underneath shouldn't.",
	},
];

export function ProblemSection() {
	const streamRef = useReveal<HTMLDivElement>();

	return (
		<Frame id="problem" markBottom>
			<SectionHead
				label="THE PROBLEM"
				n="01"
				sub="Most of the work is everything around it. Your company's context is scattered, permissioned, and always changing, and each new agent interface tends to solve it again from scratch."
				title={
					<>
						Every agent rebuilds the <span class="lp-red">same</span> layer.
					</>
				}
			/>
			<div class="lp-hard lp-stream" ref={streamRef}>
				{HARD_PARTS.map((part) => (
					<a class="lp-hardcell lp-srow" href={part.href} key={part.n}>
						<span class="hn">
							<HardIcon d={part.icon} />
							{part.n}
						</span>
						<h3>{part.title}</h3>
						<p>{part.body}</p>
					</a>
				))}
			</div>
		</Frame>
	);
}

