/**
 * Animated "proxy for the source of truth" flow for the event-sourcing post:
 *
 *   sources keep the truth → connectors observe → the append-only log
 *   (supersede, never update) → governed reads with visibility compiled
 *   into the SQL → and every agent action lands back in the log.
 *
 * The log pane plays a supersede vignette on loop: churn.def v1 dims and
 * picks up a "superseded" tag as v2 fades in pointing at it. Pure CSS
 * keyframes, no hydration.
 */

const ACCENT = "var(--color-tg-accent)";

const SOURCES = ["slack", "gmail", "stripe", "postgres", "github"];

const TICKS = [
  "left-0 top-0 -translate-x-1/2 -translate-y-1/2",
  "right-0 top-0 translate-x-1/2 -translate-y-1/2",
  "left-0 bottom-0 -translate-x-1/2 translate-y-1/2",
  "right-0 bottom-0 translate-x-1/2 translate-y-1/2",
];

function CornerTicks() {
  return (
    <>
      {TICKS.map((pos) => (
        <span
          key={pos}
          aria-hidden="true"
          class={`absolute ${pos} font-mono text-[9px] leading-none`}
          style={{ color: "var(--color-page-text-muted)" }}
        >
          +
        </span>
      ))}
    </>
  );
}

function Card({
  step,
  title,
  sub,
  grow = 1,
  children,
}: {
  step: string;
  title: string;
  sub: string;
  grow?: number;
  children: preact.ComponentChildren;
}) {
  return (
    <div
      class="relative flex min-w-0 flex-col gap-1.5 border p-3.5"
      style={{
        flex: `${grow} 1 0%`,
        borderColor: "var(--color-page-border)",
        backgroundColor: "var(--color-page-bg)",
      }}
    >
      <div class="flex items-baseline gap-1.5">
        <span
          aria-hidden="true"
          class="shrink-0 font-mono text-[9.5px]"
          style={{ color: ACCENT }}
        >
          {step}
        </span>
        <span
          class="text-[12.5px] font-semibold leading-tight"
          style={{ color: "var(--color-page-text)" }}
        >
          {title}
        </span>
      </div>
      <span
        class="text-[10px] leading-snug"
        style={{ color: "var(--color-page-text-muted)" }}
      >
        {sub}
      </span>
      {children}
    </div>
  );
}

function Chip({ label, dim = false }: { label: string; dim?: boolean }) {
  return (
    <span
      class="border px-1.5 py-0.5 font-mono text-[9.5px]"
      style={{
        color: dim ? "var(--color-page-text-muted)" : ACCENT,
        borderColor: dim
          ? "var(--color-page-border)"
          : "var(--color-page-border-active)",
        backgroundColor: "var(--color-page-surface)",
      }}
    >
      {label}
    </span>
  );
}

function Connector() {
  return (
    <div
      class="relative hidden h-px flex-[0_0_22px] self-center sm:block"
      style={{ backgroundColor: "var(--color-page-border)" }}
    >
      <span
        class="tp-pip absolute top-1/2 h-1.5 w-1.5 -translate-y-1/2"
        style={{ backgroundColor: ACCENT }}
      />
    </div>
  );
}

function LogRow({
  id,
  kind,
  cls,
  tag,
}: {
  id: string;
  kind: string;
  cls?: string;
  tag?: string;
}) {
  return (
    <div class={`flex items-center justify-between gap-2 ${cls ?? ""}`}>
      <span class="flex min-w-0 items-center gap-1.5">
        <span style={{ color: "var(--color-page-text-muted)" }}>{id}</span>
        <span class="truncate" style={{ color: "var(--color-page-text)" }}>
          {kind}
        </span>
      </span>
      {tag ? (
        <span
          class={`shrink-0 border px-1 py-px text-[8px] ${
            cls === "tp-old" ? "tp-old-tag" : ""
          }`}
          style={{
            color: "var(--color-page-text-muted)",
            borderColor: "var(--color-page-border)",
          }}
        >
          {tag}
        </span>
      ) : null}
    </div>
  );
}

export function TruthProxyDiagram() {
  return (
    <div
      class="not-prose relative my-7 border p-4"
      style={{
        borderColor: "var(--color-page-border)",
        backgroundColor: "var(--color-page-surface-dim)",
      }}
    >
      <CornerTicks />
      <div
        class="mb-3 font-mono text-[10px] uppercase tracking-[0.22em]"
        style={{ color: "var(--color-page-text-muted)" }}
      >
        A proxy for the source of truth
      </div>
      <div class="flex flex-col gap-2.5 sm:flex-row sm:items-stretch sm:gap-0">
        {/* 1. the systems of record stay put */}
        <Card step="01" title="Sources keep the truth" sub="the system of record stays put">
          <div class="mt-1 flex flex-wrap gap-1">
            {SOURCES.map((s, i) => (
              <span
                key={s}
                class="tp-src border px-1.5 py-0.5 font-mono text-[9.5px]"
                style={{
                  animationDelay: `${i * 1.4}s`,
                  color: "var(--color-page-text-muted)",
                  borderColor: "var(--color-page-border)",
                  backgroundColor: "var(--color-page-surface)",
                }}
              >
                {s}
              </span>
            ))}
          </div>
        </Card>

        <Connector />

        {/* 2. connectors observe */}
        <Card step="02" title="Connectors observe" sub="feeds pull · webhooks push">
          <div class="mt-0.5 flex flex-wrap gap-1">
            <Chip label="oauth" dim />
            <Chip label="api key" dim />
            <Chip label="browser" dim />
            <Chip label="device" dim />
          </div>
          <span
            class="mt-1 text-[9.5px] leading-snug"
            style={{ color: "var(--color-page-text-muted)" }}
          >
            agent workers hold placeholders, the proxy swaps in the real
            credential at egress
          </span>
        </Card>

        <Connector />

        {/* 3. the append-only log, supersede on loop */}
        <Card step="03" title="The append-only log" sub="never UPDATE · never DELETE" grow={1.25}>
          <div
            class="mt-0.5 flex flex-col gap-1 border px-2 py-1.5 font-mono text-[9.5px]"
            style={{
              borderColor: "var(--color-page-border)",
              backgroundColor: "var(--color-page-surface)",
            }}
          >
            <LogRow id="a1f9…" kind="slack · thread" />
            <LogRow id="b2c4…" kind="stripe · payment_failed" />
            <LogRow id="c3d7…" kind="churn.def v1" cls="tp-old" tag="superseded" />
            <div class="tp-new flex items-center justify-between gap-2">
              <span class="flex min-w-0 items-center gap-1.5">
                <span style={{ color: "var(--color-page-text-muted)" }}>d4e8…</span>
                <span class="truncate" style={{ color: ACCENT }}>
                  churn.def v2 → c3d7
                </span>
              </span>
            </div>
          </div>
        </Card>

        <Connector />

        {/* 4. governed reads */}
        <Card step="04" title="Governed reads" sub="visibility compiled into the SQL">
          <div
            class="mt-0.5 flex flex-col gap-0.5 font-mono text-[9.5px]"
            style={{ color: "var(--color-page-text-muted)" }}
          >
            <span>✓ org scope</span>
            <span>✓ connection visibility</span>
            <span>✓ resource membership</span>
          </div>
          <div class="mt-1 flex flex-wrap gap-1">
            <Chip label="agents" />
            <Chip label="dashboards" dim />
            <Chip label="MCP" dim />
          </div>
        </Card>
      </div>

      {/* loop-back rail: agent actions are new observations */}
      <div class="mt-3 flex items-center gap-2 px-1">
        <span class="font-mono text-[12px]" style={{ color: ACCENT }} aria-hidden="true">
          ←
        </span>
        <div
          class="relative h-px min-w-6 flex-1"
          style={{ backgroundColor: "var(--color-page-border)" }}
        >
          <span
            class="tp-pip-rev absolute top-1/2 h-1.5 w-1.5 -translate-y-1/2"
            style={{ backgroundColor: ACCENT }}
          />
        </div>
        <span
          class="font-mono text-[10.5px]"
          style={{ color: "var(--color-page-text-muted)" }}
        >
          every agent action is a new observation, back into the log
        </span>
      </div>

      <style>{`
        @keyframes lobu-tp-flow {
          0% { left: -4px; opacity: 0; }
          12% { opacity: 1; }
          88% { opacity: 1; }
          100% { left: calc(100% + 4px); opacity: 0; }
        }
        @keyframes lobu-tp-flow-rev {
          0% { left: calc(100% + 4px); opacity: 0; }
          12% { opacity: 1; }
          88% { opacity: 1; }
          100% { left: -4px; opacity: 0; }
        }
        .tp-pip { animation: lobu-tp-flow 2.4s linear infinite; }
        .tp-pip-rev { animation: lobu-tp-flow-rev 3s linear infinite; }
        @keyframes lobu-tp-src {
          0%, 6% { color: var(--color-page-text); border-color: var(--color-page-border-active); }
          10%, 100% { color: var(--color-page-text-muted); border-color: var(--color-page-border); }
        }
        .tp-src { animation: lobu-tp-src 7s linear infinite; }
        @keyframes lobu-tp-old {
          0%, 45% { opacity: 1; }
          55%, 100% { opacity: 0.45; }
        }
        @keyframes lobu-tp-old-tag {
          0%, 50% { opacity: 0; }
          58%, 100% { opacity: 1; }
        }
        @keyframes lobu-tp-new {
          0%, 50% { opacity: 0; transform: translateY(3px); }
          60%, 100% { opacity: 1; transform: translateY(0); }
        }
        .tp-old { animation: lobu-tp-old 7s linear infinite; }
        .tp-old .tp-old-tag { animation: lobu-tp-old-tag 7s linear infinite; }
        .tp-new { animation: lobu-tp-new 7s linear infinite; }
        @media (prefers-reduced-motion: reduce) {
          .tp-src { animation: none; }
          .tp-pip, .tp-pip-rev { animation: none; opacity: 0.6; left: 50%; }
          .tp-old { animation: none; opacity: 0.45; }
          .tp-old .tp-old-tag { animation: none; opacity: 1; }
          .tp-new { animation: none; opacity: 1; transform: none; }
        }
      `}</style>
    </div>
  );
}

