/**
 * Production OG cards — stable paths under public/og/.
 * Does not touch public/og/experiments/.
 *
 *   bun run og:build
 */
import { copyFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { writeOgPng } from "./render";
import { cardLoop } from "./templates";

const root = join(fileURLToPath(import.meta.url), "../../..");
const outDir = join(root, "public/og");

async function main() {
	mkdirSync(outDir, { recursive: true });

	const cards = [
		{
			file: "default.png",
			input: {
				eyebrow: "LOBU · OPEN SOURCE",
				title: "Build AI teammates on your company context.",
				titleAccent: "AI teammates",
				description:
					"Connect ChatGPT, Claude, Codex, Slack, and your own agents to company knowledge and tools through one secure, open-source layer.",
				footer: "lobu.ai",
			},
		},
		{
			file: "for-slackbot.png",
			input: {
				eyebrow: "SLACK · HOSTED BOT",
				title: "AI teammates that live in Slack.",
				titleAccent: "Slack",
				description:
					"Define the goal in-chat, connect company data, name who owns what — the agent runs; you approve.",
				footer: "lobu.ai/for/slackbot",
			},
		},
	] as const;

	for (const card of cards) {
		const path = join(outDir, card.file);
		await writeOgPng(path, cardLoop(card.input));
		console.log(`  ✓ /og/${card.file}`);
	}

	// Site-wide default (BaseLayout / docs head still reference /lobu-og.png)
	copyFileSync(join(outDir, "default.png"), join(root, "public/lobu-og.png"));
	console.log("  ✓ /lobu-og.png (from default.png)");
	console.log("\nShipped OG cards ready.");
}

main().catch((err) => {
	console.error(err);
	process.exit(1);
});
