import { Resvg } from "@resvg/resvg-js";
import { writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import satori from "satori";
import { loadOgFonts } from "./fonts";
import { OG_H, OG_W } from "./palette";

export async function renderPng(
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	element: any,
	width: number,
	height: number,
): Promise<Buffer> {
	const fonts = loadOgFonts();
	const svg = await satori(element, {
		width,
		height,
		fonts,
	});
	const resvg = new Resvg(svg, {
		fitTo: { mode: "width", value: width },
	});
	return Buffer.from(resvg.render().asPng());
}

export async function renderOgPng(
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	element: any,
): Promise<Buffer> {
	return renderPng(element, OG_W, OG_H);
}

export async function writeOgPng(path: string, element: unknown): Promise<void> {
	mkdirSync(dirname(path), { recursive: true });
	const png = await renderOgPng(element);
	writeFileSync(path, png);
}

export async function writePng(
	path: string,
